
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_apf_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_apf", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.387567890331157e+00, -3.323533979991954e+00, -3.233849214062694e+00, -3.109703227470759e+00, -2.940730683175206e+00, -2.716255397142763e+00, -2.428226106451409e+00, -2.076484550477742e+00, -1.675623937401478e+00, -1.257013858639297e+00, -8.518695550349552e-01, -5.861704775027469e-01, -5.110615980687049e-01, -4.199203288104179e-01, -3.030656702647272e-01, -1.927883973088531e-01, -1.093573372584915e-01, -5.184834147541164e-02, -2.320830640585047e-02, -1.293077733614787e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


